import { isOpenRedirectQueryParamKey } from './openRedirectQueryParamKeys';

/** First character of a URI scheme must be an ASCII letter (RFC 3986). */
const isAsciiLetter = (char: string): boolean =>
  (char >= 'A' && char <= 'Z') || (char >= 'a' && char <= 'z');

/** Remaining scheme characters: letters, digits, +, ., - */
const isSchemeCharacter = (char: string): boolean =>
  isAsciiLetter(char) ||
  (char >= '0' && char <= '9') ||
  char === '+' ||
  char === '.' ||
  char === '-';

/**
 * Detects values that start with a URI scheme (e.g. javascript:, data:).
 * Used to block scheme-based open-redirect gadgets in query param values.
 */
const hasLeadingUrlScheme = (value: string): boolean => {
  const colonIndex = value.indexOf(':');
  if (colonIndex <= 0) return false;

  const scheme = value.slice(0, colonIndex);
  if (!isAsciiLetter(scheme[0])) return false;

  for (let index = 1; index < scheme.length; index += 1) {
    if (!isSchemeCharacter(scheme[index])) return false;
  }

  return true;
};

/**
 * Returns whether a query param value is safe to propagate during in-app tab navigation.
 * Rejects absolute http(s) URLs, protocol-relative paths (//), and scheme-prefixed values.
 */
export const isSafeInternalNavigationQueryParamValue = (
  value: string,
): boolean => {
  const trimmed = value.trim();

  if (!trimmed) return true;

  const lowerCased = trimmed.toLowerCase();

  // Absolute external URLs (http://, https://)
  if (lowerCased.startsWith('http://') || lowerCased.startsWith('https://')) {
    return false;
  }

  // Protocol-relative URLs (//host)
  if (trimmed.startsWith('//')) return false;

  // Other schemes (javascript:, data:, etc.)
  if (hasLeadingUrlScheme(trimmed)) return false;

  return true;
};

/**
 * Sanitizes URL search params before in-app tab navigation.
 * Strips open-redirect param names and unsafe values; preserves all other query params.
 */
export const sanitizeInternalNavigationSearch = (
  searchParams: URLSearchParams,
): string => {
  const safeParams = new URLSearchParams();

  searchParams.forEach((value, key) => {
    if (isOpenRedirectQueryParamKey(key)) return;
    if (!isSafeInternalNavigationQueryParamValue(value)) return;

    safeParams.set(key, value);
  });

  return safeParams.toString();
};
